// TestInvoiceWithoutLines is the incident: an invoice the store holds without lines (a zero-amount renewal, a metered period
// with no usage) made the invoice list and get answer 500 with "index out of range [0] with length 0".
func TestInvoiceWithoutLines(t *testing.T) {
	e := apitest.New(t)
	c := e.CreateCustomer(e.Acme, "Jane", "jane@example.com")
	inv, err := e.Store.CreateInvoice(store.Invoice{OrgID: e.Acme.ID, CustomerID: c.ID, Currency: money.USD}, e.Clock.Now())
	if err != nil {
		t.Fatal(err)
	}
	var invs struct {
		Items []struct {
			ID          string `json:"id"`
			Description string `json:"description"`
		} `json:"items"`
	}
	e.MustDo(http.StatusOK, "GET", "/v1/invoices", e.Acme.Key, nil, &invs)
	if len(invs.Items) != 1 || invs.Items[0].ID != inv.ID || invs.Items[0].Description != "" {
		t.Fatalf("invoices = %+v", invs)
	}
	var got struct {
		Description string `json:"description"`
		Total       int64  `json:"total"`
	}
	e.MustDo(http.StatusOK, "GET", "/v1/invoices/"+inv.ID, e.Acme.Key, nil, &got)
	if got.Description != "" || got.Total != 0 {
		t.Fatalf("invoice = %+v", got)
	}
}

