162	func (s *Service) renew(ctx context.Context, sub store.Subscription, now time.Time) error {
163		plan, ok := s.Store.Plan(sub.OrgID, sub.PlanID)
164		if !ok {
165			return store.ErrNotFound
166		}
167		if sub.CancelAtPeriodEnd {
168			end := sub.CurrentPeriodEnd
169			sub, err := s.Store.UpdateSubscription(sub.OrgID, sub.ID, func(x *store.Subscription) error {
170				x.Status, x.CanceledAt = store.Canceled, &end
171				return nil
172			})
173			if err == nil {
174				s.publish(ctx, sub.OrgID, "subscription.canceled", sub)
175			}
176			return err
177		}
178		start := now
179		end := billing.AddInterval(start, plan.Interval)
180		paid := true
181		var err error
182		switch {
183		case plan.UsageType == store.Metered && sub.Status != store.Trialing:
184			paid, err = s.invoicePeriod(ctx, sub, plan, sub.CurrentPeriodStart, sub.CurrentPeriodEnd)
185		case plan.UsageType == store.Licensed:
186			paid, err = s.invoicePeriod(ctx, sub, plan, start, end)
187		}
188		if err != nil {
189			return err
190		}
191		sub, err = s.Store.UpdateSubscription(sub.OrgID, sub.ID, func(x *store.Subscription) error {
192			x.CurrentPeriodStart, x.CurrentPeriodEnd = start, end
193			if paid {
194				x.Status = store.Active
195			} else {
196				x.Status = store.PastDue
197			}
198			return nil
199		})
200		if err != nil {
201			return err
202		}
203		s.publish(ctx, sub.OrgID, "subscription.updated", sub)
204		return nil
205	}
206	
207	// invoicePeriod invoices one period of a subscription and charges the invoice to the customer's default payment method.
208	// It reports false when the charge was declined. An invoice that needs no charge is marked paid; one whose customer has no
209	// payment method stays open and counts as paid here (it is paid by hand). A period with nothing to bill (a metered period
210	// without usage) creates no invoice.
211	func (s *Service) invoicePeriod(ctx context.Context, sub store.Subscription, plan store.Plan, start, end time.Time) (bool, error) {
212		var lines []store.Line
213		period := start.Format("Jan 2, 2006") + " to " + end.Format("Jan 2, 2006")
214		switch plan.UsageType {
215		case store.Licensed:
216			lines = append(lines, store.Line{Description: plan.Name + ", " + period, Quantity: int64(sub.Quantity), UnitAmount: plan.UnitAmount})
217		case store.Metered:
218			if used := s.Store.UsageTotal(sub.OrgID, sub.ID, start, end); used > 0 {
219				lines = append(lines, store.Line{Description: plan.Name + " usage, " + period, Quantity: used, UnitAmount: plan.UnitAmount})
220			}
221		}
222		if len(lines) == 0 {
223			return true, nil
224		}
225		ps, pe := start, end
226		inv, err := s.Store.CreateInvoice(store.Invoice{OrgID: sub.OrgID, CustomerID: sub.CustomerID, SubscriptionID: sub.ID, Currency: plan.Currency,
227			Lines: lines, DiscountPercent: sub.DiscountPercent, PeriodStart: &ps, PeriodEnd: &pe}, s.Clock.Now())
228		if err != nil {
229			return false, err
230		}
231		s.publish(ctx, sub.OrgID, "invoice.created", map[string]any{"invoice_id": inv.ID, "subscription_id": sub.ID})
232		_, _, err = s.Payments.Pay(ctx, sub.OrgID, inv.ID, "")
233		var decline *payments.DeclineError
234		switch {
235		case err == nil, errors.Is(err, payments.ErrNoPaymentMethod):
236			return true, nil
237		case errors.As(err, &decline):
238			return false, nil
239		default:
240			return false, err
241		}
242	}
243	
244	func (s *Service) setStatus(ctx context.Context, sub store.Subscription, st store.SubStatus) (store.Subscription, error) {
245		sub, err := s.Store.UpdateSubscription(sub.OrgID, sub.ID, func(x *store.Subscription) error {
246			x.Status = st
247			return nil
248		})
249		if err == nil {
250			s.publish(ctx, sub.OrgID, "subscription.updated", sub)
251		}
252		return sub, err
253	}
254	
255	func (s *Service) publish(ctx context.Context, orgID, typ string, data any) {
256		if s.Publisher != nil {
257			_ = s.Publisher.Publish(ctx, orgID, typ, data)
258		}
259	}
